/** 握手过渡页：200 + Set-Cookie（由调用方带上）+ meta refresh 跳回干净根路径（保留 dsh-layout 等业务参数）。 */
export function handshakePageHtml(target = '/') {
  const safe = typeof target === 'string' && target.startsWith('/') && !target.startsWith('//') && !target.includes('\\') ? target : '/';
  return `<!doctype html><html lang="zh"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="refresh" content="0; url=${safe}">

